/* Productivity hub (Study Time, Cheat Sheets, Code Pulse, Workspace), Certificate, WakeMeUp, See Plans */
(function () {
  const { I, esc, av, hero, tabs, sectionHead, masthead, card, empty, seg, bar, statCard, modal, toast, register, ACTS, MENUS, D } = P;
  const PT = [{ id: 'study-room', label: 'Study Time', icon: 'timer' }, { id: 'cheatsheets', label: 'Cheat Sheets', icon: 'scroll-text' }, { id: 'cp-hub', label: 'Code Pulse', icon: 'code' }, { id: 'workspace', label: 'Workspace', icon: 'kanban' }];

  let zen = null, zs = 1500;
  function studyRoom() {
    return `<div class="main-grid"><section class="card zen"><span class="label">Focus session</span><div class="zen-ring"><svg viewBox="0 0 120 120"><circle cx="60" cy="60" r="52" stroke="var(--bg-tertiary)" stroke-width="8" fill="none"/><circle id="zring" cx="60" cy="60" r="52" stroke="var(--accent-amber)" stroke-width="8" fill="none" stroke-linecap="round" stroke-dasharray="327" stroke-dashoffset="0" transform="rotate(-90 60 60)"/></svg><div class="zen-t" id="zt">25:00</div></div>${seg('zmode', ['Pomodoro', 'Short break', 'Long break'], 'Pomodoro')}<div class="row" style="justify-content:center;margin-top:16px"><button class="btn primary" data-act="zen" id="zbtn" style="min-width:120px">${I('play', 15)}Start</button><button class="btn" data-act="zen-reset">${I('rotate-ccw', 15)}</button></div></section>
      <div class="stack">${card('Study room · 14 focusing', 'users', `<div class="row wrap" style="gap:8px">${D.members.map((m) => av(m.id, 36)).join('')}</div>`)}${card('Ambient sound', 'headphones', `<div class="grid g2">${[['Rain', 'cloud'], ['Café', 'coffee'], ['Lo-fi', 'music'], ['Library', 'library']].map(([s]) => `<button class="btn" data-act="amb" style="justify-content:flex-start">${I('music', 14)}${s}</button>`).join('')}</div>`)}${card('Today', 'activity', `<div class="row between"><div><div class="num" style="font-size:1.5rem">3h 20m</div><div class="faint" style="font-size:11px">Focused</div></div><div><div class="num" style="font-size:1.5rem">8</div><div class="faint" style="font-size:11px">Sessions</div></div></div>`)}</div></div>`;
  }
  ACTS.zen = (el) => {
    if (zen) { clearInterval(zen); zen = null; el.innerHTML = `${I('play', 15)}Resume`; return; }
    el.innerHTML = `${I('pause', 15)}Pause`;
    zen = setInterval(() => { zs = Math.max(0, zs - 15); const t = document.getElementById('zt'); if (!t) { clearInterval(zen); zen = null; return; } t.textContent = `${String(Math.floor(zs / 60)).padStart(2, '0')}:${String(zs % 60).padStart(2, '0')}`; document.getElementById('zring').style.strokeDashoffset = 327 * (1 - zs / 1500); }, 250);
  };
  ACTS['zen-reset'] = () => { clearInterval(zen); zen = null; zs = 1500; P.render(); };
  ACTS.amb = (el) => { el.parentElement.querySelectorAll('.btn').forEach((b) => b.classList.toggle('primary', b === el && !b.classList.contains('primary'))); toast('Ambient: ' + el.textContent.trim()); };

  const cheatsheets = () => `<div class="row between wrap" style="margin-bottom:14px">${seg('cs', ['All', 'CSE', 'Math', 'EEE'], 'All')}<button class="btn primary sm" data-act="toast" data-msg="Editor opened">${I('plus', 14)}New sheet</button></div><div class="grid g3">${[['Big-O cheatsheet', 'CSE', 412], ['Laplace transforms', 'Math', 289], ['SQL joins', 'CSE', 377], ['Kirchhoff & Thevenin', 'EEE', 198], ['Git commands', 'CSE', 520], ['Integration tricks', 'Math', 244]].map(([n, c, v]) => `<section class="card hoverable" data-act="preview" data-n="${n}"><div class="row between"><span class="ic-tile">${I('scroll-text', 17)}</span><span class="chip">${c}</span></div><b style="display:block;margin:12px 0 4px">${n}</b><div class="faint row" style="font-size:11.5px">${I('eye', 12)}${v} views</div></section>`).join('')}</div>`;
  const cpHub = () => `<div class="grid g4 keep2">${statCard('CF rating', '1642', '<span class="good">+38</span> last round', 'trophy')}${statCard('Solved', '587', 'This year 214', 'circle-check', 'green')}${statCard('Streak', '19d', 'Best 41d', 'flame', 'rose')}${statCard('Batch rank', '#6', 'CSE 2022', 'medal', 'cyan')}</div><div class="main-grid">${card('Upcoming contests', 'calendar', `<div class="list">${[['Codeforces Round 1012 (Div. 2)', 'Today 8:35 pm', 'amber'], ['AtCoder Beginner 412', 'Sat 6:00 pm', ''], ['AUST Intra IUPC', '30 Nov', 'green']].map(([n, t, c]) => `<div class="list-row"><span class="ic-tile ${c}">${I('code', 15)}</span><div class="grow"><div class="t">${n}</div><div class="s">${t}</div></div><button class="btn sm" data-act="toast" data-msg="Reminder set">${I('bell', 13)}</button></div>`).join('')}</div>`)}${card('Leaderboard', 'trophy', `<div class="list">${D.members.slice(0, 5).map((m, i) => `<div class="list-row"><b class="num ${i < 3 ? 'ok' : 'faint'}" style="width:20px">${i + 1}</b>${av(m.id, 28)}<div class="grow t">${m.name}</div><b class="num">${2100 - i * 140}</b></div>`).join('')}</div>`)}</div>`;
  const COLS = [['To do', ['Write SRS doc', 'Design ER diagram', 'Read paper for thesis']], ['In progress', ['OS assignment 3', 'Portfolio site']], ['Done', ['Lab report 4', 'Quiz 1 prep']]];
  const workspace = () => `<div class="kanban">${COLS.map(([c, items], ci) => `<div class="kcol" data-col="${ci}"><div class="row between" style="margin-bottom:10px"><b>${c}</b><span class="chip">${items.length}</span></div>${items.map((t) => `<div class="kcard" draggable="true">${esc(t)}<div class="row" style="margin-top:8px"><span class="chip ${ci === 2 ? 'green' : ci ? 'amber' : ''}">${['CSE 3207', 'Personal', 'CSE 3201'][t.length % 3]}</span>${av(D.members[t.length % 6].id, 20, false)}</div></div>`).join('')}<button class="btn ghost sm" style="width:100%;margin-top:6px" data-act="toast" data-msg="Card added">${I('plus', 13)}Add card</button></div>`).join('')}</div><div class="faint" style="font-size:11px;margin-top:10px">Drag cards between columns.</div>`;
  document.addEventListener('dragstart', (e) => { if (e.target.classList?.contains('kcard')) { window.__drag = e.target; e.target.style.opacity = 0.4; } });
  document.addEventListener('dragend', (e) => { if (e.target.classList?.contains('kcard')) e.target.style.opacity = 1; });
  document.addEventListener('dragover', (e) => { if (e.target.closest?.('.kcol')) e.preventDefault(); });
  document.addEventListener('drop', (e) => { const col = e.target.closest?.('.kcol'); if (col && window.__drag) { col.insertBefore(window.__drag, col.querySelector('.btn')); toast('Moved to ' + col.querySelector('b').textContent); } });

  const PV = { 'study-room': studyRoom, cheatsheets, 'cp-hub': cpHub, workspace };
  register({ path: '/productivity', title: 'Productivity', group: 'Productivity', icon: 'zap', render: (sub) => {
    sub = PV[sub] ? sub : 'study-room'; const t = PT.find((x) => x.id === sub);
    return hero({ icon: 'zap', eyebrow: 'Get things done', a: 'Produc', b: 'tivity', sub: 'Focus timer, cheat sheets, competitive programming and your kanban.' }) + tabs('/productivity', PT, sub) + `<div class="content-card">${sectionHead(t.icon, 'Productivity', t.label, { 'study-room': 'Study together, stay focused', cheatsheets: 'Quick revision sheets by AUSTians', 'cp-hub': 'Contests, ratings & leaderboards', workspace: 'Your tasks and projects' }[sub])}${PV[sub]()}</div>`;
  } });
  [['/study-time', 'study-room', 'Study Time'], ['/cheat-sheets', 'cheatsheets', 'Cheat Sheets'], ['/code-pulse', 'cp-hub', 'Code Pulse'], ['/workspace', 'workspace', 'Workspace']].forEach(([p, id, title]) => register({ path: p, title, group: 'Productivity', icon: PT.find((x) => x.id === id).icon, nav: '/productivity', hidden: true, render: () => masthead({ icon: PT.find((x) => x.id === id).icon, over: 'Productivity', title, sub: 'Standalone view', stats: [] }) + `<div class="content-card">${PV[id]()}</div>` }));

  /* Certificate */
  register({ path: '/certificate', title: 'Certificate', group: 'Productivity', icon: 'award', render: () => masthead({ icon: 'award', over: 'Tools', title: 'Certificate Maker', sub: 'Club & event certificates in bulk', stats: [['Made', '340'], ['Templates', '5']] }) +
    `<div class="grid g2"><section class="card"><div class="field"><span class="label">Event</span><input class="input" value="AUST Intra Programming Contest 2026"></div><div class="field" style="margin-top:12px"><span class="label">Recipient</span><input class="input" id="certn" value="${D.me.name}" oninput="document.getElementById('certp').textContent=this.value"></div><div class="field" style="margin-top:12px"><span class="label">Template</span>${seg('ct', ['Classic', 'Modern', 'Minimal'], 'Classic')}</div><div class="row" style="justify-content:flex-end;margin-top:16px"><button class="btn" data-act="toast" data-msg="CSV imported · 48 names">${I('upload', 14)}Import CSV</button><button class="btn primary" data-act="toast" data-msg="certificate.pdf downloaded">${I('download', 14)}Generate</button></div></section>
    <section class="card"><div class="cert"><span class="label" style="color:#7a653d">Certificate of achievement</span><div style="font-size:12px;color:#555;margin-top:14px">This is proudly presented to</div><div id="certp" class="cert-name">${D.me.name}</div><div style="font-size:12px;color:#555">for securing <b>2nd place</b> in AUST Intra Programming Contest 2026</div><div class="row between" style="margin-top:26px;font-size:10px;color:#666"><span>Convener</span><span>${I('award', 26)}</span><span>Head, CSE</span></div></div></section></div>` });

  /* WakeMeUp */
  register({ path: '/wakemeup', title: 'WakeMeUp', group: 'Productivity', icon: 'alarm-clock', render: () => masthead({ icon: 'alarm-clock', over: 'Tools', title: 'WakeMeUp', sub: 'Alarms that follow your routine', stats: [['Active', '3'], ['Next', '6:45']] }) +
    `<div class="grid g3">${[['6:45', 'Sat, Mon, Tue', '8:00 class', true], ['7:30', 'Sun, Wed', '9:30 class', true], ['6:15', 'Thu', 'Lab day', true], ['10:00', 'Fri', 'Weekend', false]].map(([t, d, n, on]) => `<section class="card"><div class="row between"><span class="num" style="font-size:2.1rem">${t}</span><span class="switch ${on ? 'on' : ''}" data-act="sw"></span></div><div class="faint" style="font-size:12px;margin-top:6px">${d}</div><span class="chip ${on ? 'amber' : ''}" style="margin-top:10px">${I('calendar-days', 11)}${n}</span></section>`).join('')}<section class="card hoverable empty" data-act="toast" data-msg="Alarm added" style="border-style:dashed">${I('plus', 24)}<b>Add alarm</b></section></div>` });

  /* See Plans */
  register({ path: '/see-plans', title: 'See Plans', group: 'Account', icon: 'crown', render: () => {
    const plans = [['Free', '৳0', ['Routine & dashboard', 'GradeLab basics', 'Community & ConnectBox'], false], ['Pro', '৳149', ['Everything in Free', 'Question Bank Analyzer', 'Unlimited Vault storage', 'All 15 themes'], true], ['Batch', '৳999', ['Pro for 10 friends', 'Private Batch Drive', 'Priority support'], false]];
    return `<div style="text-align:center;padding:20px 0 6px"><span class="chip amber">${I('crown', 12)}AUSTWise Pro</span><h1 style="font-size:clamp(1.7rem,4vw,2.5rem);letter-spacing:-.03em;margin:12px 0 6px">Pick the plan that fits <span class="ok">your semester</span></h1><p class="muted" style="margin:0">Cancel anytime. Student pricing, billed monthly.</p><div style="margin-top:16px">${seg('bill', ['Monthly', 'Semester (-20%)'], 'Monthly')}</div></div>
      <div class="grid g3 plans">${plans.map(([n, p, f, hot]) => `<section class="card plan ${hot ? 'hot' : ''}">${hot ? '<span class="chip amber" style="align-self:flex-start">Most popular</span>' : ''}<b style="font-size:16px">${n}</b><div><span class="num" style="font-size:2.3rem">${p}</span><span class="faint">/month</span></div><div class="list">${f.map((x) => `<div class="list-row" style="padding:8px 0"><span class="ok">${I('check', 15)}</span><span style="font-size:13px">${x}</span></div>`).join('')}</div><button class="btn ${hot ? 'primary' : ''}" style="margin-top:auto" data-act="plan" data-p="${n}">${n === 'Free' ? 'Current plan' : 'Upgrade to ' + n}</button></section>`).join('')}</div>`;
  } });
  ACTS.plan = (el) => { if (el.dataset.p === 'Free') return; modal({ title: 'Upgrade to ' + el.dataset.p, sub: 'Prototype — no real payment', icon: 'crown', body: `<div class="row between"><span>${el.dataset.p} plan · monthly</span><b class="num">${el.dataset.p === 'Pro' ? '৳149' : '৳999'}</b></div><div class="dashed" style="margin:0"></div><div class="field"><span class="label">Pay with</span>${seg('pay', ['bKash', 'Nagad', 'Card'], 'bKash')}</div>`, foot: `<button class="btn ghost" data-close>Cancel</button><button class="btn primary" data-go="/payment/success">Continue</button>` }); };
  register({ path: '/payment', title: 'Payment', group: 'Account', icon: 'circle-check', hidden: true, bare: true, render: (sub) => sub === 'cancel' ? `<div class="center-page"><section class="card" style="max-width:420px;text-align:center;padding:34px"><span class="ic-tile rose" style="width:64px;height:64px;margin:0 auto 14px">${P.I('x', 30)}</span><h2>Payment cancelled</h2><p class="muted">No money was taken. You are still on the Free plan.</p><button class="btn primary" data-go="/see-plans">Back to plans</button></section></div>` : `<div class="center-page"><section class="card" style="max-width:420px;text-align:center;padding:34px"><span class="ic-tile green" style="width:64px;height:64px;margin:0 auto">${I('circle-check', 30)}</span><h2 style="margin:16px 0 6px">You're Pro now 🎉</h2><p class="muted" style="margin:0 0 18px">All Pro features are unlocked on your account.</p><button class="btn primary" data-go="/dashboard">Go to dashboard</button></section></div>` });
})();
